261	.cmdk-overlay{position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:90;display:flex;align-items:flex-start;justify-content:center;padding-top:14vh}
262	.cmdk{width:560px;max-width:92%;background:var(--bg-card);border-radius:10px;box-shadow:0 12px 40px rgba(0,0,0,.35);overflow:hidden}
263	.cmdk input{width:100%;border:0;border-bottom:1px solid var(--divider);padding:16px 18px;font:inherit;font-size:16px;outline:none;background:var(--bg-card);color:var(--text-primary)}
264	.cmdk-list{max-height:320px;overflow:auto}
265	.cmdk-item{display:flex;align-items:center;gap:14px;padding:11px 18px;cursor:pointer;color:var(--text-primary)}
266	.cmdk-item .material-icons{font-size:20px;color:var(--text-secondary)}
267	.cmdk-item.sel{background:rgba(66,133,244,.12)}
268	/* Settings + help cards (centered modal) */
269	.modal-overlay.center{align-items:center;justify-content:center}
270	.settings-card,.help-card{background:var(--bg-card);width:520px;max-width:94%;border-radius:8px;box-shadow:0 8px 30px rgba(0,0,0,.3);display:flex;flex-direction:column;max-height:88vh;overflow:hidden}
271	.settings-body{padding:8px 18px 4px;overflow:auto}
272	.set-field{display:flex;flex-direction:column;gap:6px;margin:14px 0;color:var(--text-primary);font-size:14px}
273	.set-field.row{flex-direction:row;align-items:center;gap:10px}
274	.set-field>span{font-weight:500;color:var(--text-secondary);font-size:13px}
275	.set-field select{padding:8px;border:1px solid var(--divider);border-radius:6px;font:inherit;background:var(--bg-card);color:var(--text-primary)}
276	.settings-sig{min-height:80px;border:1px solid var(--divider);border-radius:6px;padding:10px;outline:none;font-size:14px}
277	.settings-sig:empty:before{content:attr(data-placeholder);color:#9aa0a6}
278	.help-body{padding:14px 20px 20px}
279	.help-row{display:flex;justify-content:space-between;gap:16px;padding:7px 0;border-bottom:1px solid var(--divider);font-size:14px;color:var(--text-primary)}
280	.help-row kbd{background:var(--bg-page);border:1px solid var(--divider);border-radius:4px;padding:2px 8px;font-family:monospace;font-size:12px;color:var(--text-primary)}
281	
282	/* ---------- Dark mode ---------- */
283	:root[data-theme="dark"]{
284	  --bg-page:#1b1c1d;--bg-card:#26282a;--divider:#3c4043;
285	  --text-primary:#e8eaed;--text-secondary:#9aa0a6;
286	  --shadow-card:0 1px 2px rgba(0,0,0,.5);--shadow-fab:0 6px 12px rgba(0,0,0,.6);
287	}
288	:root[data-theme="dark"] .chip,:root[data-theme="dark"] .attach-chip{background:#33363a;border-color:#44474b;color:#cfd2d6}
289	:root[data-theme="dark"] .reader-bar{background:var(--bg-card)}
290	:root[data-theme="dark"] .reader-overlay{background:var(--bg-page)}
291	:root[data-theme="dark"] .card.selected{background:#2b3a55}
292	:root[data-theme="dark"] .nav-item.active{background:#3a2a28}
293	:root[data-theme="dark"] .load-more,:root[data-theme="dark"] .fab-mini{background:var(--bg-card)}
294	:root[data-theme="dark"] .compose-card input,:root[data-theme="dark"] .compose-body,
295	:root[data-theme="dark"] .reply-body{background:var(--bg-card);color:var(--text-primary)}
296	:root[data-theme="dark"] .msg .mbody iframe{background:#fff;border-radius:4px}
297	:root[data-theme="dark"] .empty .material-icons{color:#8a6d00}
