  const subj = r.dataset.subject.startsWith("Re:") ? r.dataset.subject : "Re: " + r.dataset.subject;
  const fd = new FormData();
  fd.append("to", all ? (r.dataset.toAll || r.dataset.to) : r.dataset.to);
  fd.append("subject", subj);
